import {bonusModel,homeModel,emergencyModel,cardModel,cardProfiles,rupee,compact} from './finance.js';
export const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=compact;
const head=(kind,title,sub)=>`<div class="canvas-head"><span class="canvas-label">${kind}</span><span class="canvas-tag">Built around your answers</span></div><h2 id="canvas-title" tabindex="-1">${title}</h2><p class="canvas-sub">${sub}</p>`;
const kpi=(label,value,note)=>`<div class="kpi"><span>${label}</span><strong>${value}</strong><small>${note}</small></div>`;
const note=(title,text,warn=false)=>`<div class="insight ${warn?'caution':''}"><span class="insight-icon" aria-hidden="true">${warn?'!':'✦'}</span><div><strong>${title}</strong><p>${text}</p></div></div>`;
const details=text=>`<details class="assumptions"><summary>See assumptions & calculation details</summary><div>${text}</div></details>`;
const pills=(key,items,current,label)=>`<div class="control-group"><span class="control-label">${label}</span><div class="segmented" role="group" aria-label="${label}">${items.map(([v,l])=>`<button data-setting="${key}" data-value="${v}" aria-pressed="${String(v)===String(current)}">${l}</button>`).join('')}</div></div>`;
function lineChart(series,labels,description){
 const values=series.flatMap(s=>s.values),min=Math.min(0,...values),max=Math.max(1,...values),range=max-min;
 const x=i=>52+i*560/(labels.length-1),y=v=>170-(v-min)/range*145;
 return `<figure class="forecast"><svg viewBox="0 0 640 210" role="img" aria-label="${esc(description)}">${[0,.5,1].map(t=>`<line x1="52" y1="${170-t*145}" x2="612" y2="${170-t*145}" stroke="#e4e8f2" stroke-dasharray="3 5"/><text x="43" y="${174-t*145}" text-anchor="end">${money(min+t*range)}</text>`).join('')}${series.map(s=>`<polyline points="${s.values.map((v,i)=>`${x(i)},${y(v)}`).join(' ')}" stroke="${s.color}" stroke-width="3" fill="none" stroke-linecap="round" stroke-linejoin="round"/><circle cx="${x(s.values.length-1)}" cy="${y(s.values.at(-1))}" r="4" fill="${s.color}"/>`).join('')}${labels.map((l,i)=>i===0||i===labels.length-1||i===Math.floor(labels.length/2)?`<text x="${x(i)}" y="196" text-anchor="middle">${l}</text>`:'').join('')}</svg><figcaption>${series.map(s=>`<span><i style="background:${s.color}"></i>${s.name}</span>`).join('')}</figcaption></figure>`;
}
function bars(rows){const min=Math.min(0,...rows.map(r=>r.value)),max=Math.max(1,...rows.map(r=>r.value)),range=max-min;return `<div class="bar-chart">${rows.map(r=>`<div class="bar-row"><div class="bar-heading"><span>${r.name}</span><strong>${money(r.value)}</strong></div><div class="bar-track"><div class="bar-fill" style="left:${(Math.min(0,r.value)-min)/range*100}%;width:${Math.max(.3,Math.abs(r.value)/range*100)}%;background:${r.value<0?'#c46a50':'#5652df'}"></div></div></div>`).join('')}</div>`;}
function bonusView(s,a){
 const rows=bonusModel({rate:s.rate,years:a.years}),selected=s.plan|| (a.buffer==='low'?'cash':a.goal),r=rows.find(x=>x.id===selected),baseline=rows.find(x=>x.id==='invest');
 const pieces=[['Repayment',r.prepay,'#5652df'],['Investments',r.invest,'#19a68e'],['Cash',r.cash,'#f0b963']];
 let stop=0;const gradient=pieces.map(([,v,color])=>{const start=stop;stop+=v/3000;return `${color} ${start}% ${stop}%`;}).join(',');
 return head('ALLOCATION PLANNER','Give every rupee a purpose.',`Your ₹3 lakh bonus · ${a.years}-year horizon`)+
 pills('plan',rows.map(x=>[x.id,{repay:'Repay',split:'50 / 50',invest:'Invest',cash:'Keep cash'}[x.id]]),selected,'Explore an allocation')+
 `<div class="allocation-layout"><div class="allocation-ring" style="background:conic-gradient(${gradient})" role="img" aria-label="${pieces.map(([label,v])=>label+' '+rupee(v)).join(', ')}"><div><small>YOUR BONUS</small><strong>₹3L</strong></div></div><div class="allocation-legend">${pieces.map(([l,v,c])=>`<div><span><i style="background:${c}"></i>${l}</span><strong>${rupee(v)}</strong></div>`).join('')}</div></div>`+
 `<div class="kpi-grid">${kpi('Interest avoided',money(baseline.interest-r.interest),'Over the selected horizon')}${kpi('Projected net position',money(r.net),'Investments + cash − loan')}${kpi('Debt-free milestone',r.debtFree?`Month ${r.debtFree}`:'Beyond this view',r.debtFree?`${60-r.debtFree} months earlier than the original term`:`${money(r.debt)} remaining at year ${a.years}`)}</div>`+
 `<div class="what-if"><div class="what-if-top"><label for="rate">Explore an investment-return assumption</label><output for="rate">${s.rate}% / year</output></div><input type="range" id="rate" data-range="rate" min="-5" max="15" step="1" value="${s.rate}" aria-valuetext="${s.rate}% per year"><div class="range-labels"><span>−5% · Downside</span><span>15% · Optimistic</span></div></div>`+
 `<h3 class="section-title">How the four paths compare</h3><p class="micro-copy">Net position after ${a.years} years, with the same monthly budget.</p>`+bars(rows.map(r=>({...r,value:r.net})))+
 note(a.buffer==='low'?'Liquidity deserves a place in this decision.':'Your priorities and the highest return may differ.',a.buffer==='low'?'You mentioned a two-month emergency buffer. Repaying or investing the full bonus would leave that buffer unchanged. Cash keeps options open.':'Repayment reduces loan interest under the fixed-rate assumption. Investing offers uncertain growth. A split lets you explore both benefits.')+
 details(`<p>The loan is ₹7.8 lakh at a fixed 8.7%, with 60 months remaining. Each path keeps the same ${rupee(r.payment)} monthly budget; freed EMI is invested after early repayment. Investment returns compound monthly at the selected annual rate ÷ 12. Cash earns 0%.</p><p>Interest avoided is measured against making no prepayment over the same horizon. Net position subtracts remaining loan from investments and cash; it excludes your existing emergency fund. Taxes, fees and prepayment charges are excluded. Investment growth is a scenario, not a forecast.</p>`);
}
function homeView(s,a){
 const years=s.years||a.years,r=homeModel({years,growth:s.growth}),over=r.firstMonthly>a.budget,points=Array.from({length:years+1},(_,i)=>homeModel({years:i,growth:s.growth}));
 return head('HOME DECISION WORKSPACE','Two ways to build your future.',`₹1.38cr home · ₹40L upfront cash · You value ${a.priority==='flex'?'flexibility':'stability'}`)+
 pills('years',[[3,'3 years'],[7,'7 years'],[12,'12 years']],years,'Time in this home')+
 `<div class="home-options"><article><div class="option-eyebrow">KEEP RENTING</div><strong>₹48,000<span> / month to start</span></strong><p>Keep your upfront money invested and your next move flexible.</p><div>Projected investments<strong>${money(r.renter)}</strong></div></article><article class="ownership"><div class="option-eyebrow">BUY THIS HOME</div><strong>${money(r.firstMonthly)}<span> / month to start</span></strong><p>Your own home, with a larger monthly commitment.</p><div>Projected net sale proceeds<strong>${money(r.owner)}</strong></div></article></div>`+
 `<div class="affordability"><div><strong>Monthly comfort check</strong><span>${rupee(r.firstMonthly)} ownership / ${rupee(a.budget)} comfortable</span></div><meter min="0" max="${Math.max(a.budget*1.5,r.firstMonthly)}" value="${r.firstMonthly}" optimum="0" low="${a.budget*.8}" high="${a.budget}">${Math.round(r.firstMonthly/a.budget*100)}%</meter><p>${over?'Over your comfort level by '+rupee(r.firstMonthly-a.budget):'Within your stated comfort level'} · includes maintenance</p></div>`+
 `<h3 class="section-title">Wealth over time</h3>`+lineChart([{name:'Rent + invest',color:'#18a78e',values:points.map(x=>x.renter)},{name:'Buy, then sell',color:'#5652df',values:points.map(x=>x.owner)}],points.map((_,i)=>i===0?'Today':'Year '+i),`At year ${years}, renting: ${rupee(r.renter)}; buying: ${rupee(r.owner)}.`)+
 pills('growth',[[2,'Slow · 2%'],[5,'Base · 5%'],[8,'Strong · 8%']],s.growth,'Home appreciation scenario')+
 note(`${r.difference>0?'Buying':'Renting'} leads by ${money(Math.abs(r.difference))} in this scenario.`,over?'The monthly ownership cost is also above your comfort level. Consider affordability separately from the long-term projection.':`Your preference for ${a.priority==='flex'?'freedom to move':'a permanent home'} is a separate part of this decision. Try another stay length to see what changes.`,over)+
 details(`<p>Purchase costs are 7% (${rupee(r.buyCosts)}), paid from ₹40 lakh upfront. The rest is the down payment; a ${rupee(r.loan)} loan runs 20 years at 8.5%. Ownership cost starts with EMI plus maintenance at 1% of home value per year.</p><p>Rent and maintenance grow 5% annually. The renter invests upfront cash and any monthly savings at 8%, compounded monthly. If renting becomes more expensive, the owner invests that difference. Buying wealth assumes sale at the selected appreciation rate, less 2% sale costs and remaining debt. Tax, renovation, insurance, and investment fees are excluded.</p>`);
}
function emergencyView(s,a){
 const rows=emergencyModel({delay:s.delay,essential:a.essential}),selected=s.plan||(a.priority==='buffer'?'fd':'savings'),r=rows.find(x=>x.id===selected),months=Array.from({length:7},(_,i)=>emergencyModel({delay:i,essential:a.essential}).find(x=>x.id===selected));
 return head('CASH-FLOW DASHBOARD','Know how much breathing room you have.',`₹1 lakh unexpected expense · ${rupee(a.essential)} monthly essentials`)+
 `<div class="funding-methods" role="group" aria-label="Choose how to fund the expense">${rows.map(x=>`<button data-setting="plan" data-value="${x.id}" aria-pressed="${selected===x.id}"><span>${x.id==='savings'?'₹':x.id==='fd'?'▥':'◷'}</span><strong>${x.name}</strong><small>${x.emi?rupee(x.emi)+' / month':'No new monthly payment'}</small></button>`).join('')}</div>`+
 `<div class="kpi-grid">${kpi('Bank-cash runway',r.runway.toFixed(1)+' months','Before another payment is needed')}${kpi('FDs still available',money(r.fd),'Kept separate from bank cash')}${kpi('Funding cost',rupee(r.cost),r.id==='emi'?'Interest across all 12 instalments':r.id==='fd'?'Assumed penalty / lost interest':'No borrowing cost')}</div>`+
 `<h3 class="section-title">Your next six months</h3><p class="micro-copy">Bank cash remaining with no incoming payments. Select a month to inspect it.</p><div class="runway-grid" role="group" aria-label="Inspect payment delay">${months.slice(1).map((x,i)=>`<button data-setting="delay" data-value="${i+1}" class="${x.afterDelay<0?'shortfall':''}" aria-pressed="${s.delay===i+1}"><span>Month ${i+1}</span><strong>${money(x.afterDelay)}</strong><i style="height:${Math.max(4,Math.min(100,Math.abs(x.afterDelay)/200000*100))}%"></i><small>${x.afterDelay<0?'Shortfall':'Cash left'}</small></button>`).join('')}</div>`+
 note(`Month ${s.delay}: ${r.afterDelay<0?'a '+money(-r.afterDelay)+' cash gap':money(r.afterDelay)+' left in the bank'}`,r.afterDelay<0?`Your remaining FDs are ${money(r.fd)}. Accessing more of them or receiving income earlier would change this picture. ${r.emi?'The EMI continues even if a client pays late.':''}`:`${r.name} gives this cash position after the expense. ${r.emi?'It preserves savings today, but adds a bill each month.':'You avoid an additional monthly bill.'}`,r.afterDelay<0)+
 details('<p>Starting bank savings: ₹2 lakh; FDs: ₹3 lakh. The ₹1 lakh expense is paid immediately. FD withdrawal assumes ₹1,000 lost interest / penalty. EMI is a 12-month loan at 15%, with no other fees.</p><p>Cash = starting bank balance after expense − months × (essentials + EMI) − FD cost where applicable. Negative values are shortfalls, not negative savings accounts. FD balances, future income and interest earnings are outside the bank-cash chart.</p>');
}
function cardView(s,a){
 const rows=cardModel({...a,year:s.year}),best=rows.find(x=>x.eligible),selected=rows.find(x=>x.id===s.card)||best;
 const p=cardProfiles[a.profile];
 return head('PERSONALISED CARD SHORTLIST','A card that fits your everyday.',`${rupee(selected.total)} / month · ${a.prime?'Prime member':'No Prime'} · ${a.fee==='none'?'No-fee preference':'Open to paid cards'}`)+
 `<div class="shortlist-intro"><span>3 real products, compared for your sample budget</span><small>Select a card to explore it</small></div><div class="card-carousel" role="group" aria-label="Choose a credit card">${rows.map(c=>`<button class="credit-tile ${c.id}" data-setting="card" data-value="${c.id}" aria-pressed="${c.id===selected.id}"><div class="card-face"><span class="bank-wordmark">${c.bank}</span><strong>${c.name}</strong><span class="card-design-label">${c.id==='icici'?'amazon pay':c.id==='sbi'?'CASHBACK CREDIT CARD':'MILLENNIA CREDIT CARD'}</span></div><div class="card-info"><span class="fit-badge">${c.id===best.id?'Matches your preferences':!c.eligible?'Has a fee condition':'Alternative to explore'}</span><h3>${c.headline}</h3><strong>${rupee(c.net)}<small> estimated annual net value*</small></strong><span class="select-card">${c.id===selected.id?'✓ Selected':'Explore this card'}</span></div></button>`).join('')}</div>`+
 pills('year',[['first','First year'],['renewal','Renewal year']],s.year,'Compare fees over time')+
 `<section class="card-detail"><div class="detail-heading"><div><span class="option-eyebrow">SELECTED CARD</span><h3>${selected.bank} ${selected.name}</h3></div><a href="${selected.source}" target="_blank" rel="noopener noreferrer">Issuer details</a></div><div class="kpi-grid">${kpi('Rewards / year',rupee(selected.rewards),'At the selected sample spending')}${kpi(s.year==='first'?'Joining fee + tax':'Renewal fee + tax',rupee(selected.annualFee),s.year==='renewal'&&selected.waiver?'Spending condition met in this model':'Standard fee used; offers excluded')}${kpi('Net annual value*',rupee(selected.net),'Before any redemption charges')}</div><p>${selected.benefit}</p><p class="redemption-note"><strong>How you use it:</strong> ${selected.redemption}</p>${!selected.eligible?'<p class="preference-note">This card has a fee or waiver condition; you asked for unconditional no-fee.</p>':''}</section>`+
 `<details class="spending-details"><summary>Your sample monthly spending</summary><div class="spend-breakdown">${[['Amazon shopping',p.amazon],['HDFC listed brands',p.partners],['Other eligible online',p.online],['Eligible offline',p.offline],['Excluded spending',p.excluded]].map(([l,v])=>`<div><span>${l}</span><strong>${rupee(v)}</strong></div>`).join('')}</div></details>`+
 `<p class="canvas-footnote">*Illustrative estimate, not a card offer or eligibility decision. Real products; independently styled tiles. Terms checked 10 Oct 2026.</p>`+
 details(`<p>Same monthly budget repeated for 12 cycles. HDFC: 5% on Amazon + listed-brand categories, capped at ₹1,000/month; 1% on remaining eligible spending, capped at ₹1,000/month. SBI: 5% eligible online and 1% offline, each capped at ₹2,000/cycle under the April 2026 revision. ICICI: 5% eligible Amazon purchases with Prime, 3% without; 1% other eligible purchases here. No Amazon Pay partner-checkout bonus is assumed.</p><p>Fees: HDFC ₹1,000, SBI ₹999, ICICI nil; 18% tax assumed on fees. First-year estimates subtract the standard joining fee. Renewal waivers use eligible annual spend above ₹1 lakh for HDFC and at least ₹2 lakh for SBI. No welcome or milestone benefits, Prime subscription costs, redemption charges, interest, EMI spend, or fees on excluded categories are included. The excluded budget earns zero on all cards. Actual MCCs, billing cycles and issuer rules govern rewards.</p><p>Sources: <a href="https://www.hdfc.bank.in/credit-cards/millennia-credit-card" target="_blank" rel="noopener">HDFC product & linked terms</a> · <a href="https://www.sbicard.com/cashback-revised" target="_blank" rel="noopener">SBI cap revision</a> · <a href="https://www.sbicard.com/en/most-important-terms-and-conditions.page" target="_blank" rel="noopener">SBI fees</a> · <a href="https://www.icici.bank.in/personal-banking/cards/credit-card/amazon-pay-credit-card" target="_blank" rel="noopener">ICICI product</a>.</p>`);
}
export function canvas(s,a){return ({bonus:bonusView,home:homeView,emergency:emergencyView,card:cardView})[s.id](s,a);}
export function summary(s,a){
 if(s.id==='bonus'){const r=bonusModel({rate:s.rate,years:a.years}).find(x=>x.id===(s.plan||(a.buffer==='low'?'cash':a.goal)));return `${r.name} leaves a projected net position of ${rupee(r.net)} after ${a.years} years at the ${s.rate}% investment-return assumption. ${a.buffer==='low'?'Your small emergency buffer makes liquidity worth weighing carefully.':'Your separate emergency buffer gives you more room to explore the alternatives.'}`;}
 if(s.id==='home'){const years=s.years||a.years,r=homeModel({years,growth:s.growth});return `Over ${years} years at ${s.growth}% home appreciation, ${r.difference>0?'buying':'renting'} leads by ${rupee(Math.abs(r.difference))} in this model. Ownership starts at ${rupee(r.firstMonthly)} per month. You value ${a.priority==='flex'?'flexibility':'stability'}; that deserves a place beside the numbers.`;}
 if(s.id==='emergency'){const r=emergencyModel({delay:s.delay,essential:a.essential}).find(x=>x.id===(s.plan||(a.priority==='buffer'?'fd':'savings')));return `${r.name} leaves ${rupee(r.afterDelay)} in bank cash after ${s.delay} months without income. ${r.afterDelay<0?'That negative number is a shortfall to plan for.':''} Your remaining fixed deposits are ${rupee(r.fd)}, shown separately.`;}
 const rows=cardModel({...a,year:s.year}),r=rows.find(x=>x.id===s.card)||rows.find(x=>x.eligible);return `${r.bank} ${r.name} gives about ${rupee(r.net)} annual value after the ${s.year==='first'?'joining':'renewal'} fee in this sample, before redemption charges. ${r.redemption} ${!r.eligible?'It does not meet your unconditional no-fee preference.':''} Check issuer terms and eligibility before making a choice.`;
}
